const raw = $input.first().json;
const body = raw.body && typeof raw.body === 'object' ? raw.body : raw;
const allowedTypes = new Set(['delivered','bounced','replied','qualified','not_qualified','meeting_booked','meeting_held','opportunity','no_opportunity','opted_out']);
const required = ['event_id','campaign_id','prospect_id','variant','event_type','occurred_at'];
const missing = required.filter(k => body[k] === undefined || body[k] === null || String(body[k]).trim() === '');
if (missing.length) throw new Error(`Missing required fields: ${missing.join(', ')}`);
if (!allowedTypes.has(body.event_type)) throw new Error(`Unsupported event_type: ${body.event_type}`);
if (body.event_type === 'sent') throw new Error('This demo does not accept or send outbound messages.');
if (!['A','B'].includes(String(body.variant))) throw new Error('variant must be A or B');
const occurred = new Date(body.occurred_at);
if (Number.isNaN(occurred.getTime())) throw new Error('occurred_at must be a valid ISO-8601 date');
const safe = {
  event_id: String(body.event_id).trim(),
  campaign_id: String(body.campaign_id).trim(),
  prospect_id: String(body.prospect_id).trim(),
  variant: String(body.variant),
  event_type: String(body.event_type),
  occurred_at: occurred.toISOString(),
  source: body.source ? String(body.source).slice(0, 200) : 'manual_demo',
  evidence_note: body.evidence_note ? String(body.evidence_note).slice(0, 500) : '',
  authorization: 'demo_only',
  send_enabled: false
};
return [{json:safe}];
